UPDATE companies SET description='Compulink Cable Assemblies Inc. was founded in 1984 in St. Petersburg, Florida. The company specializes in wire harness assembly and custom molded cable assemblies for a range of high-reliability markets.

Compulink manufactures cable and wire harness assemblies that incorporate printed circuit boards, fans, switches, power supplies, and panel assemblies. Its capabilities span wire harness assembly, custom overmolding, coaxial and RF cable assembly, electromechanical box builds, control panel fabrication, and low-pressure molding. The company operates a crimp quality assurance lab equipped with a Schleuniger MicroGraph System for cross-sectional analysis, and offers engineering support, rapid prototyping, quick-turn production, and first-article inspection. Production runs from prototype through low-rate initial to full volume.

The company serves original equipment manufacturers and military contractors across defense, medical, industrial, commercial, transportation, and renewable energy sectors. Its ITAR-registered, AS9100D- and ISO 9001:2015-certified facility produces military harnesses and molded assemblies deployed in defense equipment worldwide, as well as RF and coaxial cables for commercial and industrial applications.

Compulink emphasizes a performance-based culture built on lean manufacturing, automation, and continuous improvement. Every team member is trained to IPC/WHMA-A-620 workmanship standards, with in-house Level A instructors. The company welcomes customer audits of its quality system and facilities, and maintains documented procedures for traceability, corrective action, and crimp monitoring.', certifications=ARRAY['ISO 9001:2015','AS9100D:2016','ITAR/EAR Registered','IPC/WHMA-A-620 Workmanship','UL/CSA Compliant']::text[], profile='{"capabilities": ["Wire harness assembly", "Custom molded cable assemblies", "Coaxial cable assembly", "RF/microwave coax assemblies", "Electromechanical assembly", "Box build", "Control panel fabrication", "Low pressure molding", "Overmolding", "Crimp quality assurance (pull testing, cross-sectional analysis)", "Engineering support services", "Rapid prototyping", "Quick-turn production", "First article inspection", "Component sourcing recommendations", "Printed circuit board integration", "Build-to-print manufacturing", "Lean manufacturing", "Automation", "ITAR/EAR compliance", "IPC/WHMA-A-620 workmanship training", "UL/CSA compliance"], "industries": ["Defense", "Medical", "Industrial", "Commercial", "Transportation", "Renewable Energy", "OEM", "High Reliability"], "materials": [], "equipment": ["Schleuniger\u00ae MicroGraph System (MGS)"], "volume": "Prototype to volume production", "lead_time": "", "tolerances": "", "built_on": ["ITAR/EAR registered for defense work", "AS9100D:2016 and ISO 9001:2015 certified quality system", "In-house IPC/WHMA-A-620 training with Level A instructors", "Crimp quality lab with Schleuniger MicroGraph cross-section analysis", "Lean manufacturing and automation to reduce customer cost"], "facts_used": ["Founded 1984 in St. Petersburg, Florida -> db", "Manufactures wire harnesses and custom molded cable assemblies -> /", "Incorporates PCBs, fans, switches, power supplies, panel assemblies -> /", "Capabilities: wire harness assembly, coax assemblies, electromechanical assemblies, custom molded cable assemblies -> /", "Crimp quality assurance lab with Schleuniger MicroGraph System -> /quality", "Engineering services, rapid prototyping, quick turn service -> /", "Low pressure molding -> /", "ITAR certified manufacturer of military wire harnesses -> /", "Serves OEMs and military contractors nationwide -> /", "ISO 9001:2015 certified -> /quality", "AS9100D:2016 certified -> /quality", "IPC/WHMA-A-620 workmanship training, Level A instructors in-house -> /quality", "ITAR/EAR registered -> /quality", "UL/CSA compliant -> /quality", "Lean manufacturing, automation, continuous improvement -> /", "Industries: defense, medical, industrial, commercial, transportation, renewable energy (solar/wind) -> /, /quality", "Performance-based culture, welcomes customer audits -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Compulink manufactures cable and wire harness assemblies that incorporate printed circuit boards, fans, switches, power supplies, panel assemblies and other high level components for industrial, military and medical applications.", "founded_year": "1984", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": ["ITAR registered", "EAR registered"], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='compulink-cable-assemblies-inc' AND approved AND profile IS NULL;
